:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --canvas-bg: #0f3460;
  --snake: #e94560;
  --food: #f5c542;
  --grid: rgba(255, 255, 255, 0.03);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--primary);
}

.score-area {
  display: flex;
  align-items: baseline;
  gap: 8px;
  background: rgba(255, 255, 255, 0.05);
  padding: 6px 14px;
  border-radius: 8px;
}

.score-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.score-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  overflow: hidden;
  background: var(--canvas-bg);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(15, 52, 96, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  display: none;
}

.overlay-content {
  text-align: center;
  max-width: 280px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.overlay-content h2 {
  font-size: 1.25rem;
  color: var(--primary);
}

.overlay-content p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.6;
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: 2px solid var(--primary);
  border-radius: 10px;
  background: transparent;
  color: var(--primary);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.1s ease;
  min-height: 48px;
}

.btn:hover {
  background: var(--primary);
  color: #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--primary-hover);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.btn.primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.instructions {
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.instructions strong {
  color: var(--text);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 14px;
    font-size: 0.95rem;
  }
}

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const overlay = document.getElementById('overlay');
const overlayTitle = document.getElementById('overlay-title');
const overlayMessage = document.getElementById('overlay-message');
const overlayBtn = document.getElementById('overlay-btn');
const pauseBtn = document.getElementById('pause-btn');
const restartBtn = document.getElementById('restart-btn');

const GRID = 20;
const CELL = canvas.width / GRID;

let snake, dir, nextDir, food, score, state, tickTimer, speed;

function resetGame() {
  snake = [{ x: 10, y: 10 }];
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  score = 0;
  speed = 150;
  state = 'paused';
  scoreEl.textContent = '0';
  spawnFood();
  draw();
  showOverlay('How to Play', 'Use arrow keys to move.<br>Eat the food, avoid walls and yourself.', 'Start');
  pauseBtn.textContent = 'Pause';
  pauseBtn.setAttribute('aria-label', 'Pause game');
  clearInterval(tickTimer);
}

function spawnFood() {
  let pos;
  do {
    pos = {
      x: Math.floor(Math.random() * GRID),
      y: Math.floor(Math.random() * GRID)
    };
  } while (snake.some(s => s.x === pos.x && s.y === pos.y));
  food = pos;
}

function draw() {
  ctx.fillStyle = '#0f3460';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = 'rgba(255,255,255,0.03)';
  ctx.lineWidth = 1;
  for (let i = 0; i <= GRID; i++) {
    ctx.beginPath();
    ctx.moveTo(i * CELL, 0);
    ctx.lineTo(i * CELL, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * CELL);
    ctx.lineTo(canvas.width, i * CELL);
    ctx.stroke();
  }

  ctx.fillStyle = '#f5c542';
  ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

  snake.forEach((seg, i) => {
    ctx.fillStyle = i === 0 ? '#e94560' : '#b83a50';
    ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
  });
}

function showOverlay(title, message, btnText) {
  overlayTitle.textContent = title;
  overlayMessage.innerHTML = message;
  overlayBtn.textContent = btnText;
  overlay.classList.remove('hidden');
}

function hideOverlay() {
  overlay.classList.add('hidden');
}

function startGame() {
  state = 'running';
  hideOverlay();
  pauseBtn.textContent = 'Pause';
  pauseBtn.setAttribute('aria-label', 'Pause game');
  clearInterval(tickTimer);
  tickTimer = setInterval(tick, speed);
}

function pauseGame() {
  if (state !== 'running') return;
  state = 'paused';
  clearInterval(tickTimer);
  pauseBtn.textContent = 'Resume';
  pauseBtn.setAttribute('aria-label', 'Resume game');
  showOverlay('Paused', 'Press Space or click Resume to continue.', 'Resume');
}

function resumeGame() {
  if (state !== 'paused') return;
  startGame();
}

function togglePause() {
  if (state === 'running') pauseGame();
  else if (state === 'paused') resumeGame();
}

function gameOver() {
  state = 'over';
  clearInterval(tickTimer);
  showOverlay('Game Over', `Final score: <strong>${score}</strong><br>Press Restart to try again.`, 'Restart');
  pauseBtn.textContent = 'Pause';
  pauseBtn.setAttribute('aria-label', 'Pause game');
}

function tick() {
  if (state !== 'running') return;

  dir = nextDir;
  const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

  if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
    gameOver();
    return;
  }

  if (snake.some(s => s.x === head.x && s.y === head.y)) {
    gameOver();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    scoreEl.textContent = score;
    spawnFood();
    if (speed > 60) {
      speed -= 5;
      clearInterval(tickTimer);
      tickTimer = setInterval(tick, speed);
    }
  } else {
    snake.pop();
  }

  draw();
}

function handleKey(e) {
  const key = e.key;
  if (key === ' ' || key === 'Spacebar') {
    e.preventDefault();
    togglePause();
    return;
  }

  if (state === 'running') {
    const dirs = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };
    const newDir = dirs[key];
    if (newDir) {
      e.preventDefault();
      if (newDir.x !== -dir.x || newDir.y !== -dir.y) {
        nextDir = newDir;
      }
    }
  }
}

overlayBtn.addEventListener('click', () => {
  if (state === 'over') {
    resetGame();
    startGame();
  } else if (state === 'paused') {
    resumeGame();
  } else {
    startGame();
  }
});

pauseBtn.addEventListener('click', togglePause);

restartBtn.addEventListener('click', () => {
  resetGame();
  startGame();
});

document.addEventListener('keydown', handleKey);

resetGame();
